//! Validation status of every calculated quantity (requirement VAL-054).
//!
//! The V&V matrix `validation/matrix.json` is generated by the Python harness and embedded here, so
//! the Rust code and the release gate read the same file. A quantity shows one of four states; a
//! quantity the matrix does not name shows "not validated" with the reason, never a blank.
//!
//! Each report type lists its numeric outputs in a catalogue: a calculated output names the
//! quantity it is an instance of, anything else says why it is not a calculated number (an
//! authored input, a conversion of one, a count). A test walks a report's JSON and fails on a
//! number that is in neither list, so a new number cannot be added without a state.

use crate::transport::{ProducedParticle, ScoreDefinition};
use serde::{Deserialize, Serialize};
use std::{collections::BTreeMap, fmt::Write as _, sync::OnceLock};

/// The matrix as committed. Read at build time; a test compares it with the file in the repository.
pub const MATRIX_JSON: &str = include_str!("../../../validation/matrix.json");

/// The registry of the calculated quantities, for the test that keeps `Quantity` in step with it.
#[cfg(test)]
const QUANTITIES_JSON: &str = include_str!("../../../validation/quantities.json");

/// What the matrix says about a quantity that it names no row for.
pub const MISSING_WHY: &str = "this quantity is not in the validation matrix";
pub const MISSING_NEXT_STEP: &str = "add it to validation/quantities.json and regenerate the matrix with `python3 -m validation matrix`";

#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq, Eq, PartialOrd, Ord)]
pub enum ValidationState {
    #[serde(rename = "validated within range")]
    ValidatedWithinRange,
    #[serde(rename = "validated but out of range")]
    ValidatedOutOfRange,
    #[serde(rename = "code-to-code only")]
    CodeToCodeOnly,
    #[default]
    #[serde(rename = "not validated")]
    NotValidated,
}

impl ValidationState {
    pub const ALL: [ValidationState; 4] = [
        Self::ValidatedWithinRange,
        Self::ValidatedOutOfRange,
        Self::CodeToCodeOnly,
        Self::NotValidated,
    ];

    /// The words the matrix and every export use.
    pub fn label(self) -> &'static str {
        match self {
            Self::ValidatedWithinRange => "validated within range",
            Self::ValidatedOutOfRange => "validated but out of range",
            Self::CodeToCodeOnly => "code-to-code only",
            Self::NotValidated => "not validated",
        }
    }

    pub fn parse(text: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|s| s.label() == text)
    }

    /// Two letters for a place with no room for the words (a PDF table row).
    pub fn code(self) -> &'static str {
        match self {
            Self::ValidatedWithinRange => "VR",
            Self::ValidatedOutOfRange => "VO",
            Self::CodeToCodeOnly => "CC",
            Self::NotValidated => "NV",
        }
    }
}

/// The calculated quantities of requirement VAL-050, with the ids of `validation/quantities.json`.
#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq, Eq, PartialOrd, Ord)]
#[serde(rename_all = "snake_case")]
pub enum Quantity {
    Tbr,
    Heating,
    Flux,
    Fluence,
    Dpa,
    GasProduction,
    Activation,
    DecayHeat,
    ShutdownDoseRate,
    TritiumInventory,
    Availability,
    NetElectricPower,
}

impl Quantity {
    pub const ALL: [Quantity; 12] = [
        Self::Tbr,
        Self::Heating,
        Self::Flux,
        Self::Fluence,
        Self::Dpa,
        Self::GasProduction,
        Self::Activation,
        Self::DecayHeat,
        Self::ShutdownDoseRate,
        Self::TritiumInventory,
        Self::Availability,
        Self::NetElectricPower,
    ];

    /// The id in the registry and the matrix.
    pub fn id(self) -> &'static str {
        match self {
            Self::Tbr => "tbr",
            Self::Heating => "heating",
            Self::Flux => "flux",
            Self::Fluence => "fluence",
            Self::Dpa => "dpa",
            Self::GasProduction => "gas_production",
            Self::Activation => "activation",
            Self::DecayHeat => "decay_heat",
            Self::ShutdownDoseRate => "shutdown_dose_rate",
            Self::TritiumInventory => "tritium_inventory",
            Self::Availability => "availability",
            Self::NetElectricPower => "net_electric_power",
        }
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Tbr => "tritium breeding ratio",
            Self::Heating => "nuclear heating",
            Self::Flux => "neutron flux",
            Self::Fluence => "fluence",
            Self::Dpa => "displacements per atom",
            Self::GasProduction => "gas production",
            Self::Activation => "activation",
            Self::DecayHeat => "decay heat",
            Self::ShutdownDoseRate => "shutdown dose rate",
            Self::TritiumInventory => "tritium inventory",
            Self::Availability => "availability",
            Self::NetElectricPower => "net electric power",
        }
    }

    /// A short name for the tag beside a number.
    pub fn short(self) -> &'static str {
        match self {
            Self::Tbr => "TBR",
            Self::Heating => "heating",
            Self::Flux => "flux",
            Self::Fluence => "fluence",
            Self::Dpa => "dpa",
            Self::GasProduction => "gas",
            Self::Activation => "activation",
            Self::DecayHeat => "decay heat",
            Self::ShutdownDoseRate => "dose rate",
            Self::TritiumInventory => "tritium",
            Self::Availability => "availability",
            Self::NetElectricPower => "net power",
        }
    }

    pub fn from_id(id: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|q| q.id() == id)
    }
}

/// What the matrix says about one quantity, as plain text.
#[derive(Clone, Debug, Serialize, PartialEq, Eq)]
pub struct ValidationNote {
    pub state: ValidationState,
    /// What the benchmarks behind the state cover, or what no benchmark covers.
    pub scope: String,
    pub why: String,
    pub next_step: String,
}

#[derive(Deserialize)]
struct MatrixFile {
    rows: Vec<MatrixRow>,
}

#[derive(Deserialize)]
struct MatrixRow {
    quantity: String,
    benchmark_id: String,
    status: String,
    reason: String,
    next_step: String,
    not_covered: String,
}

/// Every matrix row's state parses, or the first that does not.
pub fn check_matrix(json: &str) -> Result<(), String> {
    let file: MatrixFile = serde_json::from_str(json).map_err(|e| e.to_string())?;
    for row in &file.rows {
        if ValidationState::parse(&row.status).is_none() {
            return Err(format!(
                "{} ({}): '{}' is not one of the four states",
                row.quantity, row.benchmark_id, row.status
            ));
        }
    }
    Ok(())
}

/// One note per quantity from the rows of the matrix. A quantity with several benchmark rows
/// takes the failing state first (out of range shows if any benchmark is), then the strongest
/// evidence; its why and next step come from the rows in that state, and the scope lists them all.
fn build_table(json: &str) -> Result<BTreeMap<String, ValidationNote>, String> {
    let file: MatrixFile = serde_json::from_str(json).map_err(|e| e.to_string())?;
    let mut by_quantity: BTreeMap<String, Vec<(ValidationState, MatrixRow)>> = BTreeMap::new();
    for row in file.rows {
        let state = ValidationState::parse(&row.status)
            .ok_or_else(|| format!("'{}' is not one of the four states", row.status))?;
        by_quantity
            .entry(row.quantity.clone())
            .or_default()
            .push((state, row));
    }
    let mut table = BTreeMap::new();
    for (quantity, rows) in by_quantity {
        // Declaration order of the enum: within range, out of range, code-to-code, not validated.
        let state = if rows
            .iter()
            .any(|(s, _)| *s == ValidationState::ValidatedOutOfRange)
        {
            ValidationState::ValidatedOutOfRange
        } else {
            rows.iter().map(|(s, _)| *s).min().unwrap_or_default()
        };
        let mut whys: Vec<String> = Vec::new();
        let mut nexts: Vec<String> = Vec::new();
        let mut scopes: Vec<String> = Vec::new();
        let mut ids: Vec<String> = Vec::new();
        for (row_state, row) in &rows {
            let (reason, scope) = match row.reason.split_once(". Scope: ") {
                Some((reason, scope)) => (reason.to_string(), scope.to_string()),
                None => (row.reason.clone(), row.not_covered.clone()),
            };
            if *row_state == state {
                if !whys.contains(&reason) {
                    whys.push(reason);
                }
                if !nexts.contains(&row.next_step) {
                    nexts.push(row.next_step.clone());
                }
                if row.benchmark_id != "none" {
                    ids.push(row.benchmark_id.clone());
                }
            }
            if !scopes.contains(&scope) {
                scopes.push(scope);
            }
        }
        let mut why = whys.join("; ");
        if !ids.is_empty() {
            let _ = write!(why, " ({})", ids.join(", "));
        }
        table.insert(
            quantity,
            ValidationNote {
                state,
                scope: scopes.join("; "),
                why,
                next_step: nexts.join("; "),
            },
        );
    }
    Ok(table)
}

static TABLE: OnceLock<Result<BTreeMap<String, ValidationNote>, String>> = OnceLock::new();

fn table() -> &'static Result<BTreeMap<String, ValidationNote>, String> {
    TABLE.get_or_init(|| build_table(MATRIX_JSON))
}

/// The note for a quantity id. An id the matrix does not name, or a matrix that cannot be read,
/// gives "not validated" with the reason and what to do.
pub fn note_for_id(id: &str) -> ValidationNote {
    match table() {
        Ok(table) => table.get(id).cloned().unwrap_or_else(|| ValidationNote {
            state: ValidationState::NotValidated,
            scope: "nothing: no matrix row".into(),
            why: MISSING_WHY.into(),
            next_step: MISSING_NEXT_STEP.into(),
        }),
        Err(problem) => ValidationNote {
            state: ValidationState::NotValidated,
            scope: "nothing: the matrix could not be read".into(),
            why: format!("the embedded validation matrix could not be read: {problem}"),
            next_step: "regenerate validation/matrix.json with `python3 -m validation matrix`"
                .into(),
        },
    }
}

pub fn note(quantity: Quantity) -> ValidationNote {
    note_for_id(quantity.id())
}

/// A quantity and its state when a report was made.
#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq, Eq)]
pub struct ValidationMark {
    pub quantity: Quantity,
    pub state: ValidationState,
}

impl ValidationMark {
    pub fn current(quantity: Quantity) -> Self {
        Self {
            quantity,
            state: note(quantity).state,
        }
    }

    /// The short tag beside a number, for example `[not validated: flux]`.
    pub fn tag(&self) -> String {
        format!("[{}: {}]", self.state.label(), self.quantity.short())
    }
}

/// How one numeric output of a report is classed.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Class {
    /// A calculated number: an instance of this quantity.
    Calculated(Quantity),
    /// A calculated number whose quantity depends on the record it sits in (a tally's score
    /// names it); `quantity_of_score` gives it and the owner of the record builds the marks.
    ByScore,
    /// Not a calculated number, with the reason: an authored input, a conversion of one, a count.
    NotCalculated(&'static str),
}

/// One named output of a report type. The name is the field name in the report's JSON.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Output {
    pub name: &'static str,
    pub class: Class,
}

pub const fn calculated(name: &'static str, quantity: Quantity) -> Output {
    Output {
        name,
        class: Class::Calculated(quantity),
    }
}

pub const fn by_score(name: &'static str) -> Output {
    Output {
        name,
        class: Class::ByScore,
    }
}

pub const fn not_calculated(name: &'static str, why: &'static str) -> Output {
    Output {
        name,
        class: Class::NotCalculated(why),
    }
}

/// The state of each calculated output of a report, by output name. Empty in a report written
/// before the field existed; a reader then falls back to the current matrix.
#[derive(Clone, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]
#[serde(transparent)]
pub struct ValidationMarks(pub BTreeMap<String, ValidationMark>);

impl ValidationMarks {
    /// A mark for every calculated output of the catalogue, from the matrix as embedded.
    pub fn for_catalogue(catalogue: &[Output]) -> Self {
        Self(
            catalogue
                .iter()
                .filter_map(|o| match o.class {
                    Class::Calculated(q) => Some((o.name.to_string(), ValidationMark::current(q))),
                    Class::ByScore | Class::NotCalculated(_) => None,
                })
                .collect(),
        )
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    /// The mark of an output, from the report when it has one, else from the quantity's current
    /// state.
    pub fn mark(&self, name: &str, quantity: Quantity) -> ValidationMark {
        self.0
            .get(name)
            .copied()
            .unwrap_or_else(|| ValidationMark::current(quantity))
    }

    /// The tag beside a number, for example `[not validated: flux]`.
    pub fn tag(&self, name: &str, quantity: Quantity) -> String {
        self.mark(name, quantity).tag()
    }

    /// The quantities of the report's calculated outputs, each once, in a fixed order.
    pub fn quantities(&self) -> Vec<Quantity> {
        let mut all: Vec<Quantity> = self.0.values().map(|m| m.quantity).collect();
        all.sort();
        all.dedup();
        all
    }
}

/// The block that explains the tags once per quantity: what the state is, why and what to do.
/// Empty for no quantities.
pub fn notes_block(quantities: &[Quantity], marks: &ValidationMarks) -> String {
    if quantities.is_empty() {
        return String::new();
    }
    let mut out = String::from("Validation status, once per quantity:\n");
    for &quantity in quantities {
        let note = note(quantity);
        // The state a report recorded wins over the matrix of today, so a saved report reads the
        // way it did when it was made.
        let state = marks
            .0
            .values()
            .find(|m| m.quantity == quantity)
            .map_or(note.state, |m| m.state);
        let _ = writeln!(
            out,
            "  {}: {}. Why: {}. Next: {}.",
            quantity.label(),
            state.label(),
            note.why.trim_end_matches('.'),
            note.next_step.trim_end_matches('.')
        );
    }
    out
}

/// The quantity a transport score is an instance of.
///
/// A tritium-producing reaction rate is tritium breeding; any other reaction rate is an
/// activation source term. Hydrogen, deuterium, helium-3 and helium-4 production are gas
/// production; tritium production is breeding.
pub fn quantity_of_score(score: &ScoreDefinition) -> Quantity {
    match score {
        ScoreDefinition::Flux | ScoreDefinition::FluxAbove { .. } => Quantity::Flux,
        ScoreDefinition::Heating { .. } => Quantity::Heating,
        ScoreDefinition::ParticleProduction {
            particle: ProducedParticle::Tritium,
            ..
        } => Quantity::Tbr,
        ScoreDefinition::ParticleProduction { .. } => Quantity::GasProduction,
        ScoreDefinition::ReactionRate { reaction }
            if matches!(
                reaction.as_str(),
                "(n,t)" | "(n,nt)" | "(n,Xt)" | "(n,t2a)" | "(n,nt2a)"
            ) =>
        {
            Quantity::Tbr
        }
        ScoreDefinition::ReactionRate { .. } => Quantity::Activation,
    }
}

/// Paths of the numbers in a report's JSON whose field name is in no catalogue entry. A name
/// that is in the catalogue is not entered, so a whole authored-input block or a map keyed by
/// component is classed by its own name.
pub fn unclassified_numbers(json: &serde_json::Value, catalogue: &[Output]) -> Vec<String> {
    fn walk(
        value: &serde_json::Value,
        key: &str,
        path: &str,
        catalogue: &[Output],
        found: &mut Vec<String>,
    ) {
        use serde_json::Value;
        match value {
            Value::Number(_) => {
                if !catalogue.iter().any(|o| o.name == key) {
                    found.push(path.to_string());
                }
            }
            Value::Object(map) => {
                for (k, v) in map {
                    if catalogue.iter().any(|o| o.name == k) {
                        continue;
                    }
                    walk(v, k, &format!("{path}.{k}"), catalogue, found);
                }
            }
            Value::Array(items) => {
                for (i, v) in items.iter().enumerate() {
                    walk(v, key, &format!("{path}[{i}]"), catalogue, found);
                }
            }
            _ => {}
        }
    }
    let mut found = Vec::new();
    walk(json, "", "$", catalogue, &mut found);
    found
}

#[cfg(test)]
mod tests {
    use super::*;

    // Verifies: VAL-054
    #[test]
    fn the_embedded_matrix_is_the_file_in_the_repository() {
        let on_disk = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/../../validation/matrix.json"
        ))
        .unwrap();
        assert_eq!(MATRIX_JSON, on_disk);
    }

    // Verifies: VAL-054
    #[test]
    fn every_state_in_the_matrix_parses_and_every_quantity_has_a_note() {
        check_matrix(MATRIX_JSON).unwrap();
        for quantity in Quantity::ALL {
            let note = note(quantity);
            assert!(
                !note.why.is_empty() && !note.next_step.is_empty(),
                "{quantity:?}"
            );
            assert_ne!(
                note.why, MISSING_WHY,
                "{quantity:?} is missing from the matrix"
            );
        }
        let bad = MATRIX_JSON.replace("\"not validated\"", "\"sort of validated\"");
        assert!(
            check_matrix(&bad)
                .unwrap_err()
                .contains("sort of validated")
        );
    }

    // Verifies: VAL-054
    #[test]
    fn the_quantity_enum_is_the_registry() {
        let registry: serde_json::Value = serde_json::from_str(QUANTITIES_JSON).unwrap();
        let ids: Vec<&str> = registry["quantities"]
            .as_array()
            .unwrap()
            .iter()
            .map(|q| q["id"].as_str().unwrap())
            .collect();
        let ours: Vec<&str> = Quantity::ALL.iter().map(|q| q.id()).collect();
        assert_eq!(ids, ours);
        for q in Quantity::ALL {
            assert_eq!(Quantity::from_id(q.id()), Some(q));
            // The serialised name is the id.
            assert_eq!(serde_json::to_value(q).unwrap(), q.id());
        }
    }

    // Verifies: VAL-054
    #[test]
    fn a_quantity_the_matrix_lacks_is_not_validated_with_a_reason_and_a_next_step() {
        let note = note_for_id("not_a_quantity");
        assert_eq!(note.state, ValidationState::NotValidated);
        assert_eq!(note.why, MISSING_WHY);
        assert!(note.next_step.contains("python3 -m validation matrix"));
    }

    // Verifies: VAL-054
    #[test]
    fn rows_of_one_quantity_combine_with_the_failing_state_first() {
        let row = |q: &str, b: &str, status: &str| {
            format!(
                "{{\"quantity\":\"{q}\",\"benchmark_id\":\"{b}\",\"status\":\"{status}\",\
                 \"reason\":\"{status} here. Scope: scope of {b}\",\"next_step\":\"next {b}\",\
                 \"not_covered\":\"nc\"}}"
            )
        };
        let json = |rows: &[String]| format!("{{\"rows\":[{}]}}", rows.join(","));
        let table = build_table(&json(&[
            row("flux", "a/x", "validated within range"),
            row("flux", "b/y", "validated but out of range"),
            row("tbr", "c/z", "code-to-code only"),
            row("tbr", "d/w", "not validated"),
        ]))
        .unwrap();
        assert_eq!(table["flux"].state, ValidationState::ValidatedOutOfRange);
        assert_eq!(table["flux"].next_step, "next b/y");
        assert!(
            table["flux"].scope.contains("scope of a/x")
                && table["flux"].scope.contains("scope of b/y")
        );
        assert_eq!(table["tbr"].state, ValidationState::CodeToCodeOnly);
        assert!(table["tbr"].why.contains("c/z") && !table["tbr"].why.contains("d/w"));
    }

    // Verifies: VAL-054
    #[test]
    fn the_tag_and_the_notes_block_say_the_state_why_and_next_step() {
        let mark = ValidationMark::current(Quantity::Flux);
        assert_eq!(mark.tag(), "[not validated: flux]");
        let block = notes_block(
            &[Quantity::Flux, Quantity::Tbr],
            &ValidationMarks::default(),
        );
        assert!(block.starts_with("Validation status, once per quantity:\n"));
        assert!(block.contains("neutron flux: not validated. Why: "));
        assert!(block.contains("tritium breeding ratio: not validated. Why: "));
        assert_eq!(block.matches(" Next: ").count(), 2);
        assert_eq!(notes_block(&[], &ValidationMarks::default()), "");
    }

    // Verifies: VAL-054
    #[test]
    fn a_note_serialises_with_the_state_why_and_next_step() {
        let json = serde_json::to_value(note(Quantity::Tbr)).unwrap();
        assert_eq!(json["state"], "not validated");
        for key in ["scope", "why", "next_step"] {
            assert!(!json[key].as_str().unwrap().is_empty(), "{key}");
        }
    }

    #[test]
    fn scores_map_to_quantities() {
        use crate::transport::{HeatingConvention, HeatingParticleScope};
        let heating = ScoreDefinition::Heating {
            convention: HeatingConvention::Heating,
            particle_scope: HeatingParticleScope::Total,
        };
        assert_eq!(quantity_of_score(&heating), Quantity::Heating);
        assert_eq!(
            quantity_of_score(&ScoreDefinition::FluxAbove {
                energy_min_ev: 1.0e5
            }),
            Quantity::Flux
        );
        let production = |particle| ScoreDefinition::ParticleProduction {
            particle,
            score: String::new(),
        };
        assert_eq!(
            quantity_of_score(&production(ProducedParticle::Tritium)),
            Quantity::Tbr
        );
        assert_eq!(
            quantity_of_score(&production(ProducedParticle::Helium4)),
            Quantity::GasProduction
        );
        let rate = |r: &str| ScoreDefinition::ReactionRate { reaction: r.into() };
        assert_eq!(quantity_of_score(&rate("(n,t)")), Quantity::Tbr);
        assert_eq!(quantity_of_score(&rate("(n,gamma)")), Quantity::Activation);
    }

    #[test]
    fn the_walker_finds_numbers_outside_the_catalogue() {
        const CATALOGUE: &[Output] = &[
            calculated("flux", Quantity::Flux),
            not_calculated("seed", "run setting"),
            not_calculated("inputs", "authored inputs"),
        ];
        let json = serde_json::json!({
            "flux": 1.0, "seed": 3, "inputs": {"anything": 2.0},
            "nested": [{"flux": 2.0}, {"extra": 5}], "text": "x"
        });
        assert_eq!(
            unclassified_numbers(&json, CATALOGUE),
            vec!["$.nested[1].extra"]
        );
        let marks = ValidationMarks::for_catalogue(CATALOGUE);
        assert_eq!(marks.0.len(), 1);
        assert_eq!(marks.0["flux"].state, ValidationState::NotValidated);
        assert_eq!(marks.quantities(), vec![Quantity::Flux]);
    }
}
